// Copyright (c) 2001-2024 Python Software Foundation).

// Package pyuni is the Unicode character database as CPython 3.12 sees it (Unicode 15.0.0):
// the str predicates, the simple case mappings _sre uses and the full str.lower/upper/casefold
// mappings. Every answer comes from tables generated by probing CPython 3.12 itself, for all
// 0x110000 code points; Go's unicode package, which follows a newer Unicode version, is never
// consulted.
//
// Code points outside 0..0x10FFFF (including negative runes) have no properties and map to
// themselves.
package pyuni

import (
	"sort"
	"strings"
)

const (
	propAlpha = 1 << iota
	propDecimal
	propDigit
	propNumeric
	propSpace
	propPrintable
	propLower
	propUpper
	propTitle
	propCased
	propCaseIgnorable
	propIDStart
	propIDContinue
	propLineBreak
)

// MaxRune is the largest code point Python's str can hold.
const MaxRune = 0x10FFFF

type caseRun struct {
	lo, hi, step uint32
	delta        int32
}

type decimalRun struct {
	lo, hi, base uint32
}

func props(r rune) uint16 {
	if r < 0 || r > MaxRune {
		return 0
	}
	c := uint32(r)
	// the last segment whose start is <= c
	i := sort.Search(len(propStarts), func(i int) bool { return propStarts[i] > c }) - 1
	return propBits[i]
}

func has(r rune, p uint16) bool { return props(r)&p != 0 }

// IsAlpha reports whether str.isalpha() is true for the one-character string r.
func IsAlpha(r rune) bool { return has(r, propAlpha) }

// IsDecimal reports str.isdecimal() for r; re's Unicode \d matches exactly these.
func IsDecimal(r rune) bool { return has(r, propDecimal) }

// IsDigit reports str.isdigit() for r.
func IsDigit(r rune) bool { return has(r, propDigit) }

// IsNumeric reports str.isnumeric() for r.
func IsNumeric(r rune) bool { return has(r, propNumeric) }

// IsAlnum reports str.isalnum() for r (isalpha, isdecimal, isdigit or isnumeric); re's Unicode
// \w is this or the underscore.
func IsAlnum(r rune) bool {
	return has(r, propAlpha|propDecimal|propDigit|propNumeric)
}

// IsSpace reports str.isspace() for r (Py_UNICODE_ISSPACE); re's Unicode \s matches these.
func IsSpace(r rune) bool { return has(r, propSpace) }

// IsPrintable reports str.isprintable() for r; repr() escapes the characters it rejects.
func IsPrintable(r rune) bool { return has(r, propPrintable) }

// IsLower reports str.islower() for the one-character string r.
func IsLower(r rune) bool { return has(r, propLower) }

// IsUpper reports str.isupper() for the one-character string r.
func IsUpper(r rune) bool { return has(r, propUpper) }

// IsTitle reports str.istitle() for the one-character string r (an uppercase or titlecase
// character).
func IsTitle(r rune) bool { return has(r, propTitle) }

// IsCased reports whether CPython treats r as cased (_PyUnicode_IsCased), as str.title and the
// final-sigma rule do.
func IsCased(r rune) bool { return has(r, propCased) }

// IsCaseIgnorable reports _PyUnicode_IsCaseIgnorable: the characters the final-sigma rule skips.
func IsCaseIgnorable(r rune) bool { return has(r, propCaseIgnorable) }

// IsIdentifierStart reports whether r may start an identifier: chr(r).isidentifier(), which
// is XID_Start plus the underscore.
func IsIdentifierStart(r rune) bool { return has(r, propIDStart) }

// IsIdentifierContinue reports whether r may follow the first character of an identifier:
// ("a" + chr(r)).isidentifier() (XID_Continue).
func IsIdentifierContinue(r rune) bool { return has(r, propIDContinue) }

// IsLineBreak reports whether str.splitlines() ends a line at r.
func IsLineBreak(r rune) bool { return has(r, propLineBreak) }

// IsIdentifier is str.isidentifier().
func IsIdentifier(s string) bool {
	first := true
	for _, r := range s {
		if first {
			if !IsIdentifierStart(r) {
				return false
			}
			first = false
		} else if !IsIdentifierContinue(r) {
			return false
		}
	}
	return !first
}

// IsDecimalValue returns the value of the decimal digit r and true, or (0, false) when r is
// not a decimal digit (str.isdecimal). int() and float() accept exactly these digits.
func IsDecimalValue(r rune) (int, bool) {
	if r < 0 || r > MaxRune {
		return 0, false
	}
	c := uint32(r)
	i := sort.Search(len(decimalRuns), func(i int) bool { return decimalRuns[i].hi >= c })
	if i < len(decimalRuns) && decimalRuns[i].lo <= c {
		return int(c - decimalRuns[i].base), true
	}
	return 0, false
}

func mapSimple(runs []caseRun, r rune) rune {
	if r < 0 || r > MaxRune {
		return r
	}
	c := uint32(r)
	i := sort.Search(len(runs), func(i int) bool { return runs[i].hi >= c })
	if i < len(runs) && runs[i].lo <= c && (c-runs[i].lo)%runs[i].step == 0 {
		return rune(int32(c) + runs[i].delta)
	}
	return r
}

func writeMapped(b *strings.Builder, runs []caseRun, special map[rune]string, r rune) {
	if s, ok := special[r]; ok {
		b.WriteString(s)
		return
	}
	b.WriteRune(mapSimple(runs, r))
}

// SimpleLower is _PyUnicode_ToLowercase (_sre.unicode_tolower): the single code point re's
// IGNORECASE matching lowers a character to. For a character whose full lowercase mapping has
// several code points it is the first of them (U+0130 lowers to "i").
func SimpleLower(r rune) rune { return mapSimple(simpleLowerRuns, r) }

// SimpleUpper is _PyUnicode_ToUppercase: the first code point of the full uppercase mapping
// ("ß" upper-cases to "S").
func SimpleUpper(r rune) rune { return mapSimple(simpleUpperRuns, r) }

// IsSreCased is _sre.unicode_iscased: r differs from its simple lowercase or uppercase.
func IsSreCased(r rune) bool { return r != SimpleLower(r) || r != SimpleUpper(r) }

// ExtraCases returns re._casefix._EXTRA_CASES[r]: the other lowercase code points that are
// equal to the lowercase code point r under re.IGNORECASE (for "s", U+017F). It returns nil
// for code points without extra cases. The slice must not be modified.
func ExtraCases(r rune) []rune { return extraCases[r] }

func mapRunes(runs []caseRun, special map[rune]string, r rune) []rune {
	if s, ok := special[r]; ok {
		return []rune(s)
	}
	return []rune{mapSimple(runs, r)}
}

// LowerRune returns the full lowercase mapping of r without the final-sigma context (U+03A3
// gives U+03C3). It works for surrogate code points too, which a Go string cannot hold.
func LowerRune(r rune) []rune { return mapRunes(fullLowerRuns, fullLowerSpecial, r) }

// UpperRune returns the full uppercase mapping of r.
func UpperRune(r rune) []rune { return mapRunes(fullUpperRuns, fullUpperSpecial, r) }

// CaseFoldRune returns the full case folding of r.
func CaseFoldRune(r rune) []rune { return mapRunes(fullFoldRuns, fullFoldSpecial, r) }

// finalSigma is CPython's handle_capital_sigma: whether the U+03A3 at rs[i] is in the
// Final_Sigma context \p{cased}\p{case-ignorable}* Σ !(\p{case-ignorable}* \p{cased}).
func finalSigma(rs []rune, i int) bool {
	j := i - 1
	var c rune
	for ; j >= 0; j-- {
		c = rs[j]
		if !IsCaseIgnorable(c) {
			break
		}
	}
	final := j >= 0 && IsCased(c)
	if final && i+1 < len(rs) {
		for j = i + 1; j < len(rs); j++ {
			c = rs[j]
			if !IsCaseIgnorable(c) {
				break
			}
		}
		final = j == len(rs) || !IsCased(c)
	}
	return final
}

// Lower is str.lower(): the full lowercase mapping with the final-sigma rule.
func Lower(s string) string {
	if strings.ContainsRune(s, 0x3A3) {
		return string(LowerRunes([]rune(s)))
	}
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		writeMapped(&b, fullLowerRuns, fullLowerSpecial, r)
	}
	return b.String()
}

// LowerRunes is Lower on a code point slice.
func LowerRunes(rs []rune) []rune {
	out := make([]rune, 0, len(rs))
	for i, r := range rs {
		if r == 0x3A3 {
			if finalSigma(rs, i) {
				out = append(out, 0x3C2)
			} else {
				out = append(out, 0x3C3)
			}
			continue
		}
		if s, ok := fullLowerSpecial[r]; ok {
			out = append(out, []rune(s)...)
		} else {
			out = append(out, mapSimple(fullLowerRuns, r))
		}
	}
	return out
}

// Upper is str.upper(): the full uppercase mapping.
func Upper(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		writeMapped(&b, fullUpperRuns, fullUpperSpecial, r)
	}
	return b.String()
}

// CaseFold is str.casefold(): the full case folding.
func CaseFold(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		writeMapped(&b, fullFoldRuns, fullFoldSpecial, r)
	}
	return b.String()
}
